mapper.select:
SELECT od.id AS detail_id, o.id AS order_id, od.massagist_id, od.shop_id, TRIM(c.phone) AS phone, DATE(od.end_time) AS service_date, DATE(o.pay_time) AS pay_date, od.duration, COALESCE(p.coefficient, 1.00) AS project_coefficient, od.project_id, COALESCE(p.title, o.product_title) AS project_title, o.parts AS parts
WHERE AND od.end_time >= #{start} AND od.end_time < #{end}
ORDER BY od.massagist_id, od.end_time, od.id

SELECT od.id AS detail_id, o.id AS order_id, od.massagist_id, od.shop_id, od.duration, COALESCE(p.coefficient, 1.00) AS project_coefficient,
o.type AS detail_type, od.start_time, od.end_time, od.project_id, COALESCE(p.title, o.product_title) AS project_title FROM oms_order_detail od INNER JOIN s_order o ON o.id = od.order_id LEFT JOIN s_project p ON p.id = od.project_id WHERE o.state IN (1, 2) AND o.appointment_state IN (1, 2) AND o.pay_time IS NOT NULL AND od.state = 2 AND od.massagist_id IS NOT NULL
AND od.end_time >= #{start} AND od.end_time < #{end}
AND od.shop_id IN
#{shopId}
AND od.massagist_id = #{massagistId}
ORDER BY od.massagist_id, od.end_time, od.id

SELECT od.id AS detail_id, o.id AS order_id, od.massagist_id, od.shop_id, DATE(od.end_time) AS service_date, od.duration, od.project_id, COALESCE(p.title, o.product_title) AS project_title, o.parts
WHERE AND od.end_time >= #{start} AND od.end_time < #{end}
AND od.massagist_id IN #{id}
AND 1=0
AND od.shop_id IN #{id}
AND 1=0
ORDER BY od.massagist_id, od.end_time, od.id

SELECT od.id AS detail_id, o.id AS order_id, od.massagist_id, od.shop_id, TRIM(c.phone) AS phone, DATE(od.end_time) AS service_date, DATE(o.pay_time) AS pay_date, od.duration, COALESCE(p.coefficient, 1.00) AS project_coefficient, od.project_id, COALESCE(p.title, o.product_title) AS project_title, o.parts AS parts
WHERE AND DATE(o.pay_time) >= #{start} AND DATE(o.pay_time) <= #{end}
ORDER BY o.pay_time, od.id

SELECT TRIM(c.phone) AS phone, DATE(od.end_time) AS service_date, od.massagist_id, od.shop_id
WHERE AND od.end_time >= #{start} AND od.end_time < #{end}
ORDER BY od.end_time, od.id

SELECT TRIM(c.phone) AS phone,
       DATE(od.end_time) AS service_date,
       od.massagist_id,
       od.shop_id

WHERE 
  AND od.end_time >= #{historyStart}
  AND od.end_time < #{end}
  AND TRIM(c.phone) IN

    #{phone}

ORDER BY c.phone, od.end_time, od.id

WITH month_orders AS ( SELECT o.id AS order_id, o.shop_id AS shop_id, o.pay_amount AS pay_amount, TRIM(c.phone) AS phone FROM s_order o INNER JOIN c_customer c ON c.id = o.customer_id WHERE o.state IN (1, 2) AND o.appointment_state IN (1, 2) AND o.type = 0 AND o.pay_time IS NOT NULL AND o.pay_amount IS NOT NULL AND DATE(o.pay_time) >= #{start} AND DATE(o.pay_time) <= #{end} AND c.phone IS NOT NULL AND TRIM(c.phone) <> '' AND NOT EXISTS ( SELECT 1 FROM s_stat_internal_account ia WHERE ia.enabled = 1 AND ia.phone = CONVERT(TRIM(c.phone) USING utf8mb4) COLLATE utf8mb4_general_ci )
AND o.shop_id IN
#{shopId}
), month_orders_with_visit AS ( SELECT m.order_id, m.shop_id, m.pay_amount, m.phone, MIN(DATE(od.end_time)) AS visit_date FROM month_orders m INNER JOIN oms_order_detail od ON od.order_id = m.order_id AND od.state = 2 AND od.end_time IS NOT NULL GROUP BY m.order_id, m.shop_id, m.pay_amount, m.phone ), first_visits AS ( SELECT TRIM(c2.phone) AS phone, MIN(DATE(od2.end_time)) AS first_date FROM oms_order_detail od2 INNER JOIN s_order o2 ON o2.id = od2.order_id INNER JOIN c_customer c2 ON c2.id = o2.customer_id WHERE o2.state IN (1, 2) AND o2.appointment_state IN (1, 2) AND o2.type = 0 AND od2.state = 2 AND od2.end_time IS NOT NULL AND c2.phone IS NOT NULL AND TRIM(c2.phone) <> '' AND TRIM(c2.phone) IN (SELECT phone FROM month_orders) GROUP BY TRIM(c2.phone) ) SELECT m.shop_id AS shop_id, SUM(m.pay_amount) AS amount FROM month_orders_with_visit m INNER JOIN first_visits f ON f.phone = m.phone WHERE m.visit_date > f.first_date GROUP BY m.shop_id
